// Validates a quotation-delivery request. Does NOT decide whether a
// quotation is worth delivering -- that decision (that this quotation was
// approved and should be sent now) lives entirely outside this workflow.
//
// recipientPhone/quotationNumber/amount/currency/validUntil/linkToken are
// NOT input fields -- read exclusively from Postgres (quotations) later in
// this workflow. Accepting them from the caller would let arbitrary
// caller-controlled data redirect a delivery, fabricate an amount, or
// forge a quotation link; Postgres is the source of truth for all of them.

const input = $input.first().json;

function isValidOpaqueId(v, maxLength) {
  return typeof v === 'string' && v.length >= 1 && v.length <= maxLength && /^[A-Za-z0-9_-]+$/.test(v);
}
function isValidExpectedVersion(v) {
  return typeof v === 'number' && Number.isInteger(v) && v >= 1 && v <= 1000000000;
}

const idempotencyKey = input.idempotencyKey;
const quotationId = input.quotationId;
const expectedVersion = input.expectedVersion;

const idempotencyKeyValid = isValidOpaqueId(idempotencyKey, 128);
const quotationIdValid = isValidOpaqueId(quotationId, 128);
const expectedVersionValid = isValidExpectedVersion(expectedVersion);

const valid = idempotencyKeyValid && quotationIdValid && expectedVersionValid;

if (!valid) {
  return [{ json: {
    _route: 'rejected',
    quotationId: quotationIdValid ? quotationId : null,
  } }];
}

return [{ json: {
  _route: 'valid',
  idempotencyKey, quotationId, expectedVersion,
} }];

// Reached only when input validation failed -- zero database and zero
// sender-workflow calls were made, structurally guaranteed (this node only
// runs from the "Input Valid?" IF node's false output, before any Postgres
// or Execute Workflow node in this workflow).

const item = $input.first().json;
return [{ json: {
  status: 'rejected',
  quotationId: item.quotationId,
  httpStatus: null,
  providerMessageId: null,
} }];

// Single authoritative source for this workflow's trusted, hardcoded
// deployment configuration -- WhatsApp/Graph API settings and the
// quotation-link origin. Every other node that needs one of these values
// reads it from THIS node's output rather than re-declaring it, so the
// two can never diverge.
//
// EVERY value below is validated for FORMAT (not just the two that had an
// obvious shipped placeholder) -- a syntactically valid but still-wrong
// value (a malformed Graph API version, a garbage phone-number id, a
// deceptive quotation-link host) must never silently reach a real
// WhatsApp send. Validated BEFORE any Postgres call: a misconfigured
// deployment makes zero database mutations and zero sender calls, rather
// than reserving a real quotation against a broken send.

const input = $input.first().json;

// Replace every one of these with your own real values before use --
// see Setup steps. The shipped defaults are placeholders and are
// deliberately rejected below until replaced.
const GRAPH_API_VERSION = 'v21.0';
const PHONE_NUMBER_ID = '000000000000000';
const TEMPLATE_NAME = 'customer_quotation_delivery';
const LANGUAGE_CODE = 'en';
const QUOTATION_LINK_ORIGIN = 'https://quotes.example.com/q/';

const PLACEHOLDER_PHONE_NUMBER_IDS = new Set(['000000000000000']);
const RESERVED_EXAMPLE_SUFFIXES = ['example.com', 'example.org', 'example.net'];

// Format checks mirror the sender's own field validators
// (whatsapp-template-message-sender.json's "Validate & Build Request")
// so a value accepted here can never be one the sender itself would then
// reject -- there is only one place these formats are defined as policy.
function isValidGraphApiVersion(v) {
  return typeof v === 'string' && /^v\d{1,3}\.\d{1,2}$/.test(v);
}
function isValidPhoneNumberIdFormat(v) {
  return typeof v === 'string' && /^\d{5,20}$/.test(v);
}
function isValidTemplateNameFormat(v) {
  return typeof v === 'string' && v.length > 0 && v.length <= 512 && /^[a-z0-9_]+$/.test(v);
}
function isValidLanguageCodeFormat(v) {
  return typeof v === 'string' && /^[a-z]{2}(_[A-Z]{2})?$/.test(v);
}

function isAscii(s) {
  for (let i = 0; i < s.length; i++) {
    if (s.charCodeAt(i) > 127) return false;
  }
  return true;
}

function isValidLabel(label) {
  // A DNS label: 1-63 chars, letters/digits/hyphen only, never starting
  // or ending with a hyphen.
  if (label.length < 1 || label.length > 63) return false;
  if (!/^[A-Za-z0-9-]+$/.test(label)) return false;
  if (label.charAt(0) === '-' || label.charAt(label.length - 1) === '-') return false;
  return true;
}

function isIpLiteral(host) {
  // Any ':' means an IPv6 literal (or a port, already rejected earlier) --
  // reject outright. A bare dotted-quad (four all-digit labels) is also
  // rejected regardless of whether the numbers are in range -- this
  // workflow's link origin is never meant to be a raw IP address.
  if (host.indexOf(':') !== -1) return true;
  const labels = host.split('.');
  if (labels.length !== 4) return false;
  return labels.every((l) => /^[0-9]{1,3}$/.test(l) && Number(l) <= 255);
}

function isReservedExampleHost(host) {
  // Exact match OR a genuine subdomain (dot-bounded) of a reserved
  // example domain -- 'quotesexample.net' is NOT a subdomain of
  // 'example.net' and must not be blocked by a naive endsWith check.
  return RESERVED_EXAMPLE_SUFFIXES.some((suffix) => host === suffix || host.endsWith('.' + suffix));
}

function isValidHostname(host) {
  if (typeof host !== 'string') return false;
  if (host.length < 1 || host.length > 253) return false;
  if (!isAscii(host)) return false;
  const labels = host.split('.');
  if (labels.length < 2) return false; // at least two DNS labels
  for (const label of labels) {
    if (!isValidLabel(label)) return false;
  }
  return true;
}

function isValidOrigin(origin) {
  // A fixed HTTPS origin, no username/password/port/query/fragment/
  // backslash, a well-formed multi-label ASCII hostname (no leading/
  // trailing/consecutive dots, no leading/trailing hyphen on any label),
  // never localhost or an IP literal, never example.com/.org/.net or any
  // subdomain of them, always ending in '/' so the token can be safely
  // appended as its own path segment. Implemented with plain string
  // splitting and per-label checks, deliberately NOT one large nested
  // regex and NOT the URL global -- n8n's Code node sandbox does not
  // expose URL by default (confirmed by direct execution: `typeof URL`
  // is 'undefined' there even though it is a normal global in a plain
  // Node.js process).
  if (typeof origin !== 'string') return false;
  if (origin.indexOf('\\') !== -1) return false;
  const PREFIX = 'https://';
  if (origin.slice(0, PREFIX.length) !== PREFIX) return false;
  const rest = origin.slice(PREFIX.length);
  const slashIdx = rest.indexOf('/');
  if (slashIdx === -1) return false; // must have a path
  const hostPart = rest.slice(0, slashIdx);
  const pathPart = rest.slice(slashIdx);
  if (hostPart.indexOf('@') !== -1) return false;
  if (hostPart.indexOf(':') !== -1) return false;
  if (hostPart.indexOf('?') !== -1 || hostPart.indexOf('#') !== -1) return false;
  if (!isValidHostname(hostPart)) return false;
  const host = hostPart.toLowerCase();
  if (host === 'localhost') return false;
  if (isIpLiteral(host)) return false;
  if (isReservedExampleHost(host)) return false;
  if (pathPart.charAt(pathPart.length - 1) !== '/') return false;
  if (pathPart.indexOf('?') !== -1 || pathPart.indexOf('#') !== -1) return false;
  if (!/^(\/[A-Za-z0-9._-]+)*\/$/.test(pathPart)) return false;
  return true;
}

const configValid =
  isValidGraphApiVersion(GRAPH_API_VERSION) &&
  isValidPhoneNumberIdFormat(PHONE_NUMBER_ID) && !PLACEHOLDER_PHONE_NUMBER_IDS.has(PHONE_NUMBER_ID) &&
  isValidTemplateNameFormat(TEMPLATE_NAME) &&
  isValidLanguageCodeFormat(LANGUAGE_CODE) &&
  isValidOrigin(QUOTATION_LINK_ORIGIN);

if (!configValid) {
  return [{ json: {
    _route: 'config_invalid',
    quotationId: input.quotationId,
  } }];
}

return [{ json: {
  _route: 'config_valid',
  idempotencyKey: input.idempotencyKey,
  quotationId: input.quotationId,
  expectedVersion: input.expectedVersion,
  config: {
    graphApiVersion: GRAPH_API_VERSION,
    phoneNumberId: PHONE_NUMBER_ID,
    templateName: TEMPLATE_NAME,
    languageCode: LANGUAGE_CODE,
    quotationLinkOrigin: QUOTATION_LINK_ORIGIN,
  },
} }];

// Reached only when this workflow's own hardcoded deployment
// configuration (WhatsApp/Graph API settings, the quotation-link origin)
// is missing or still a shipped placeholder -- structurally guaranteed to
// run before any Postgres call in this workflow. Zero database
// mutations, zero sender calls.

const item = $input.first().json;
return [{ json: {
  status: 'configuration_required',
  quotationId: item.quotationId,
  httpStatus: null,
  providerMessageId: null,
} }];

// Classifies process_quotation_delivery(...)'s result. `route` is one of:
//   'owner_applied'       -- this call owns the idempotency reservation;
//                            result_status is the actual outcome (which
//                            may itself be terminal, or 'delivery_pending'
//                            if a sender call is still needed).
//   'duplicate_match'     -- idempotencyKey already reserved by an
//                            IDENTICAL prior request (same quotationId) --
//                            result_status is that prior request's real,
//                            durable outcome.
//   'idempotency_mismatch'-- idempotencyKey already reserved by a
//                            DIFFERENT quotationId -- zero mutation of any
//                            quotation occurred for this call.
//
// Every route except "owner_applied with result_status = delivery_pending"
// is immediately terminal -- no sender call is ever reachable from this
// node except via that one specific path.
//
// Defense in depth: result_status is allowlist-checked before it can ever
// become part of this workflow's controlled output -- an unrecognized
// value becomes a fixed literal, never an arbitrary database value
// surfaced verbatim.

const KNOWN_STATUSES = new Set([
  'missing_quotation', 'conflict', 'draft', 'cancelled', 'rejected', 'accepted',
  'expired', 'already_delivered', 'delivery_pending', 'sent', 'failed',
  'reconciliation_required', 'idempotency_mismatch', 'invalid_database_state',
]);
function sanitizeStatus(v) {
  return (typeof v === 'string' && KNOWN_STATUSES.has(v)) ? v : 'invalid_database_state';
}

const result = $input.first().json;
const validated = $('Validate Input').first().json;

const resultStatus = sanitizeStatus(result.result_status);
const needsSend = result.route === 'owner_applied' && resultStatus === 'delivery_pending';

return [{ json: {
  _route: needsSend ? 'needs_send' : 'finalized',
  resultStatus,
  idempotencyKey: validated.idempotencyKey,
  quotationId: validated.quotationId,
  expectedVersion: validated.expectedVersion,
  recipientPhone: result.out_recipient_phone,
  quotationNumber: result.out_quotation_number,
  totalMinorUnits: result.out_total_minor_units,
  currency: result.out_currency,
  validUntil: result.out_valid_until,
  linkToken: result.out_link_token,
} }];

// Reached for: duplicate replays, idempotency mismatches, missing
// quotations, version conflicts, draft/cancelled/rejected/accepted
// quotations, expired quotations, and already-delivered/pending
// deliveries. None of these paths reach the sender sub-workflow --
// structurally guaranteed by the IF node that routes here.

const classified = $('Classify Reserve Result').first().json;

return [{ json: {
  status: classified.resultStatus,
  quotationId: classified.quotationId,
  httpStatus: null,
  providerMessageId: null,
} }];

// Builds the sender sub-workflow's request for confirmed-eligible
// deliveries only -- reached only after Postgres durably recorded
// 'delivery_pending' for this quotation. recipientPhone and every quote
// value come EXCLUSIVELY from Postgres (read back from the atomic
// reservation call) -- never from caller input. templateName,
// languageCode, graphApiVersion, and phoneNumberId are all trusted,
// hardcoded configuration -- not caller input.
//
// The quotation link is NEVER a caller- or database-supplied full URL --
// it is always this fixed HTTPS origin plus the opaque, already
// CHECK-constrained linkToken read from Postgres, re-validated here as
// defense in depth before ever being used to build a URL. There is no
// host/scheme/userinfo a compromised database row could use to redirect
// this link anywhere else.
//
// Money is formatted from integer minor units using pure string/integer
// manipulation -- never JavaScript floating-point division -- see
// formatMinorUnits below.
//
// Every configuration value below is read from "Load Configuration" --
// the single authoritative, already-validated source for this workflow's
// trusted deployment settings -- never re-declared here, so the two can
// never diverge.

const c = $input.first().json;
const config = $('Load Configuration').first().json.config;

const GRAPH_API_VERSION = config.graphApiVersion;
const PHONE_NUMBER_ID = config.phoneNumberId;
const TEMPLATE_NAME = config.templateName;
const LANGUAGE_CODE = config.languageCode;
const QUOTATION_LINK_ORIGIN = config.quotationLinkOrigin;

function isValidLinkToken(v) {
  return typeof v === 'string' && v.length >= 16 && v.length <= 128 && /^[A-Za-z0-9_-]+$/.test(v);
}

function formatMinorUnits(minorUnits) {
  // Postgres BIGINT columns are returned by the driver as a numeric
  // STRING, not a JS number, specifically to avoid silent precision loss
  // for values near/above Number.MAX_SAFE_INTEGER -- both shapes are
  // accepted here, but formatting itself is always pure string slicing,
  // never a numeric division, regardless of which shape arrived.
  let s;
  if (typeof minorUnits === 'number' && Number.isInteger(minorUnits) && Number.isSafeInteger(minorUnits) && minorUnits >= 0) {
    s = String(minorUnits);
  } else if (typeof minorUnits === 'string' && /^[0-9]{1,15}$/.test(minorUnits)) {
    s = minorUnits;
  } else {
    return null;
  }
  const padded = s.padStart(3, '0');
  const whole = padded.slice(0, -2);
  const frac = padded.slice(-2);
  return whole + '.' + frac;
}

if (!isValidLinkToken(c.linkToken)) {
  // Fail closed -- never build or send a link from an unvalidated token.
  // idempotencyKey is included so this structurally-should-be-unreachable
  // path can still finalize honest durable state -- see "Finalize Invalid
  // Send Request".
  return [{ json: { _route: 'invalid_link', quotationId: c.quotationId, idempotencyKey: c.idempotencyKey } }];
}

const formattedTotal = formatMinorUnits(c.totalMinorUnits);
if (formattedTotal === null) {
  return [{ json: { _route: 'invalid_amount', quotationId: c.quotationId, idempotencyKey: c.idempotencyKey } }];
}

const quotationLink = QUOTATION_LINK_ORIGIN + encodeURIComponent(c.linkToken);

return [{ json: {
  _route: 'valid',
  idempotencyKey: c.idempotencyKey,
  quotationId: c.quotationId,
  recipientPhone: c.recipientPhone,
  templateName: TEMPLATE_NAME,
  languageCode: LANGUAGE_CODE,
  graphApiVersion: GRAPH_API_VERSION,
  phoneNumberId: PHONE_NUMBER_ID,
  bodyParameters: [c.quotationNumber, formattedTotal, c.currency, c.validUntil, quotationLink],
} }];

// Reached only if Postgres returned a linkToken or totalMinorUnits that
// somehow fails this workflow's own defense-in-depth re-validation despite
// the database's own CHECK constraints -- structurally should be
// unreachable in normal operation, but fails closed with honest durable
// semantics rather than ever building a request from unvalidated data or
// leaving a stranded delivery_pending reservation. Zero sender calls
// occur; "Finalize Invalid Send Request" (run just before this node) has
// already recorded the event and moved the state out of delivery_pending
// via the same ownership-verified finalize function used for real sends.
//
// Defense in depth: out_result_status is allowlist-checked before
// becoming this workflow's controlled `status` -- an unrecognized value
// becomes a fixed literal, never an arbitrary database value surfaced
// verbatim.

const KNOWN_STATUSES = new Set([
  'invalid_database_state', 'reconciliation_required',
  'finalize_unknown_key', 'finalize_mismatch', 'finalize_invalid_outcome',
  'finalize_invalid_provider_message_id',
]);
function sanitizeStatus(v) {
  return (typeof v === 'string' && KNOWN_STATUSES.has(v)) ? v : 'invalid_database_state';
}

const finalizeResult = $input.first().json;
const item = $('Build Send Request').first().json;
return [{ json: {
  status: sanitizeStatus(finalizeResult.out_result_status),
  quotationId: item.quotationId,
  httpStatus: null,
  providerMessageId: null,
} }];

// Classifies the sender sub-workflow's own controlled output
// ({status, httpStatus, providerMessageId} -- see
// whatsapp-template-message-sender.json). A send is only ever treated as
// successful when EVERY field is mutually consistent -- status exactly
// 'sent', httpStatus a genuine 2xx integer, and providerMessageId a
// non-empty, bounded, safely-charactered identifier. The sender can
// return status:'sent' with a null providerMessageId for a malformed 2xx
// provider response (missing `messages` field) -- that is a malformed
// send, not a genuine one, and must never be recorded as sent.

function isValidProviderMessageId(v) {
  return typeof v === 'string' && v.length >= 1 && v.length <= 256 && /^[A-Za-z0-9_.=-]+$/.test(v);
}

const resp = $input.first().json;
const req = $('Build Send Request').first().json;

const httpStatusValid = typeof resp.httpStatus === 'number' && Number.isInteger(resp.httpStatus);
const httpStatusOk = httpStatusValid && resp.httpStatus >= 200 && resp.httpStatus < 300;
const providerMessageIdValid = isValidProviderMessageId(resp.providerMessageId);

// Every field must agree before this counts as a genuine success.
const sentValid = resp.status === 'sent' && httpStatusOk && providerMessageIdValid;
const outcome = sentValid ? 'sent' : 'failed';

return [{ json: {
  outcome,
  idempotencyKey: req.idempotencyKey,
  quotationId: req.quotationId,
  httpStatus: httpStatusValid ? resp.httpStatus : null,
  // Non-sent (and internally-inconsistent sent-shaped) outcomes never
  // retain a provider message id -- there is nothing genuinely confirmed.
  providerMessageId: sentValid ? resp.providerMessageId : null,
} }];

// Reached after the ownership-verified, version-guarded finalize write.
// If ownership no longer matches (a newer attempt already owns this
// quotation, or the quotation moved on since this attempt's reservation),
// the result is 'reconciliation_required' -- never falsely reported as
// full success -- and the newer/current state was never touched. A replay
// against an already-terminal attempt returns that attempt's real,
// existing result, never flips it.
//
// Defense in depth: out_result_status is allowlist-checked before
// becoming this workflow's controlled `status` -- an unrecognized value
// becomes a fixed literal, never an arbitrary database value surfaced
// verbatim.

const KNOWN_STATUSES = new Set([
  'sent', 'failed', 'reconciliation_required', 'invalid_database_state',
  'finalize_unknown_key', 'finalize_mismatch', 'finalize_invalid_outcome',
  'finalize_invalid_provider_message_id',
]);
function sanitizeStatus(v) {
  return (typeof v === 'string' && KNOWN_STATUSES.has(v)) ? v : 'invalid_database_state';
}

const finalizeResult = $input.first().json;
const classified = $('Classify Send Result').first().json;

return [{ json: {
  status: sanitizeStatus(finalizeResult.out_result_status),
  quotationId: classified.quotationId,
  httpStatus: classified.httpStatus,
  providerMessageId: classified.providerMessageId,
} }];
